#!/usr/bin/env python3
"""One-pass census of real `entire <verb>` invocations across agent transcripts.

Extracts shell commands ONLY from command-shaped keys in tool-CALL contexts
(never tool results / stdout), normalizes shell text, and matches `entire ...`
only in command position at the start of a segment.
"""
import json, os, re, sys, collections
from pathlib import Path

HOME = Path.home()
ROOTS = [
    ("claude",   HOME / ".claude" / "projects"),
    ("codex",    HOME / ".codex"),
    ("copilot",  HOME / ".copilot"),
    ("factory",  HOME / ".factory"),
    ("gemini",   HOME / ".gemini"),
    ("opencode", HOME / ".opencode"),
    ("pi",       HOME / ".pi"),
]

COMMAND_KEYS = {"command", "cmd", "script", "argv", "shell_command", "commandLine", "command_line"}
PARSE_KEYS   = {"arguments", "args", "input", "tool_input", "toolInput", "rawInput", "params"}
BLOCKED_KEYS = {"toolUseResult", "tool_result", "toolResult", "output", "stdout", "stderr",
                "result", "results", "response", "aggregated_output", "formatted_output",
                "error", "exec_output", "outputs", "new_string", "old_string", "content_diff"}
RESULT_TYPES = {"tool_result", "function_call_output", "tool_output", "exec_command_output"}
CONFIG_BASENAMES = {"settings.json", "settings.local.json", "config.json", "mcp.json",
                    "installed_plugins.json", "keybindings.json"}

HINT = "recover the intent behind existing code"

SHELLS = {"bash", "sh", "zsh", "fish", "dash"}
WRAPPERS = {"sudo", "time", "exec", "env", "nohup", "nice", "command", "builtin", "eval", "export"}
KEYWORDS = {"then", "do", "else", "elif", "if", "while", "until", "!", "{", "("}
GROUPS = {"session", "sessions", "checkpoint", "cp", "checkpoints", "agent", "auth", "doctor",
          "org", "project", "repo", "grant", "labs", "trail", "hooks", "mcp", "review"}

heredoc_re = re.compile(r"<<-?\s*['\"]?(\w+)['\"]?.*?(?:\n\1\b|\Z)", re.S)
shell_c_re = re.compile(r"^\s*(?:\S*/)?(?:bash|sh|zsh|fish|dash)\s+(?:-\S+\s+)*-l?c\s+(['\"])(.*)\1\s*$", re.S)
assign_re = re.compile(r"[A-Za-z_][A-Za-z0-9_]*=\S*$")

key_census = collections.Counter()      # (agent, json path) -> count of command-key hits
blocked_hits = collections.Counter()    # (agent, json path) -> command-keys skipped in result contexts
entire_census = collections.Counter()   # verb phrase -> count (deduped)
target_matches = []                     # dicts for eyeballing
census_examples = collections.defaultdict(list)
seen_dedup = set()
config_file_hits = collections.Counter()
hint_files = {}                         # file -> (min_ts, max_ts)
stats = collections.Counter()
per_agent_files = collections.Counter()
per_agent_bytes = collections.Counter()
parse_fail_lines = collections.Counter()
skipped_files = []


def extract_cmd_strings(v):
    out = []
    if isinstance(v, str):
        if v.strip():
            out.append(v)
    elif isinstance(v, list) and v and all(isinstance(x, str) for x in v):
        if v[0].rsplit("/", 1)[-1] in SHELLS:
            for i in range(1, len(v)):
                if re.fullmatch(r"-l?c", v[i]) and i + 1 < len(v):
                    out.append(v[i + 1])
                    break
            else:
                out.append(" ".join(v))
        else:
            out.append(" ".join(v))
    return out


def walk(obj, path, blocked, hits, ctx):
    if isinstance(obj, dict):
        t = obj.get("type")
        if isinstance(t, str) and t in RESULT_TYPES:
            blocked = True
        for k, v in obj.items():
            kb = blocked or (k in BLOCKED_KEYS)
            np = f"{path}.{k}" if path else k
            if k in COMMAND_KEYS:
                cmds = extract_cmd_strings(v)
                if cmds:
                    if kb:
                        blocked_hits[(ctx["agent"], np)] += len(cmds)
                    else:
                        key_census[(ctx["agent"], np)] += len(cmds)
                        for c in cmds:
                            hits.append((np, c))
            if isinstance(v, str) and k in PARSE_KEYS and 2 <= len(v) < 2_000_000 and v.lstrip()[:1] in "{[":
                try:
                    pv = json.loads(v)
                except Exception:
                    pv = None
                if pv is not None:
                    walk(pv, np + "*", kb, hits, ctx)
            if isinstance(v, (dict, list)):
                walk(v, np, kb, hits, ctx)
    elif isinstance(obj, list):
        for it in obj:
            if isinstance(it, (dict, list)):
                walk(it, path + "[]", blocked, hits, ctx)


def normalize_segments(cmd):
    cmd = cmd[:200_000]
    m = shell_c_re.match(cmd)
    if m:
        cmd = m.group(2)
    if "<<" in cmd:
        cmd = heredoc_re.sub(" HEREDOC ", cmd)
    c = re.sub(r"'[^']*'", " QUOTED ", cmd)
    c = re.sub(r'"(?:\\.|[^"\\])*"', " QUOTED ", c)
    return re.split(r"\|\||&&|[;\n|&`]|\$\(", c)


def first_command_tokens(seg):
    toks = seg.strip().split()
    i = 0
    while i < len(toks):
        t = toks[i].lstrip("({")
        if not t or t in KEYWORDS or t in WRAPPERS or assign_re.fullmatch(t):
            i += 1
            continue
        if t == "timeout":
            i += 2
            continue
        return toks[i:]
    return None


def entire_verbs(toks):
    base = toks[0].lstrip("({").rsplit("/", 1)[-1]
    rest = None
    if base in ("entire", "entire-dev"):
        rest = toks[1:]
    elif base == "go" and len(toks) >= 3 and toks[1] == "run" and "cmd/entire" in toks[2]:
        rest = toks[3:]
    if rest is None:
        return None, None
    verbs = []
    for t in rest:
        if t.startswith("-"):
            if not verbs:
                verbs.append(t)
            break
        verbs.append(t.strip("'\""))
        if len(verbs) == 2:
            break
    if not verbs:
        return base, "(bare)"
    if verbs[0] in GROUPS and len(verbs) > 1:
        return base, f"{verbs[0]} {verbs[1]}"
    return base, verbs[0]


def classify_target(phrase):
    if phrase == "why":
        return "entire why"
    p = phrase.split()
    if len(p) == 2 and p[0] in ("checkpoint", "cp", "checkpoints") and p[1] == "search":
        return "entire checkpoint search"
    return None


def process_command(agent, fpath, ts, path, cmd, lineno):
    for seg in normalize_segments(cmd):
        toks = first_command_tokens(seg)
        if not toks:
            continue
        binbase, phrase = entire_verbs(toks)
        if phrase is None:
            continue
        dedup_key = (cmd.strip(), ts if ts else f"{fpath}:{lineno}")
        is_dup = dedup_key in seen_dedup
        seen_dedup.add(dedup_key)
        if fpath.name in CONFIG_BASENAMES:
            config_file_hits[phrase] += 1
            continue
        if is_dup:
            stats["deduped_progress_copies"] += 1
            continue
        entire_census[phrase] += 1
        if len(census_examples[phrase]) < 3:
            census_examples[phrase].append(cmd.strip().replace("\n", " ⏎ ")[:200])
        tgt = classify_target(phrase)
        if tgt:
            target_matches.append({
                "target": tgt, "agent": agent, "file": str(fpath), "ts": ts,
                "json_path": path, "binary": binbase,
                "cmd": cmd.strip().replace("\n", " ⏎ ")[:300],
            })


def scan_line_obj(agent, fpath, obj, raw_ts, lineno):
    hits = []
    ctx = {"agent": agent}
    walk(obj, "", False, hits, ctx)
    for path, cmd in hits:
        process_command(agent, fpath, raw_ts, path, cmd, lineno)


def get_ts(obj):
    if isinstance(obj, dict):
        for k in ("timestamp", "ts", "created_at", "createdAt", "time"):
            v = obj.get(k)
            if isinstance(v, str) and len(v) >= 8:
                return v
    return None


def scan_file(agent, fpath):
    try:
        size = fpath.stat().st_size
    except OSError:
        return
    if size > 500 * 1024 * 1024:
        skipped_files.append((str(fpath), f"{size} bytes > 500MB cap"))
        return
    per_agent_files[agent] += 1
    per_agent_bytes[agent] += size
    has_hint = False
    tmin = tmax = None
    if fpath.suffix == ".jsonl":
        try:
            with open(fpath, "r", errors="replace") as f:
                for lineno, line in enumerate(f):
                    if HINT in line:
                        has_hint = True
                    line = line.strip()
                    if not line:
                        continue
                    try:
                        obj = json.loads(line)
                    except Exception:
                        parse_fail_lines[agent] += 1
                        continue
                    ts = get_ts(obj)
                    if ts:
                        if tmin is None or ts < tmin:
                            tmin = ts
                        if tmax is None or ts > tmax:
                            tmax = ts
                    scan_line_obj(agent, fpath, obj, ts, lineno)
        except OSError as e:
            skipped_files.append((str(fpath), f"read error: {e}"))
            return
    else:  # .json
        try:
            text = fpath.read_text(errors="replace")
        except OSError as e:
            skipped_files.append((str(fpath), f"read error: {e}"))
            return
        if HINT in text:
            has_hint = True
        try:
            obj = json.loads(text)
        except Exception:
            parse_fail_lines[agent] += 1
            obj = None
        if obj is not None:
            scan_line_obj(agent, fpath, obj, get_ts(obj), 0)
    if has_hint:
        if tmin is None:
            import datetime
            mt = datetime.datetime.fromtimestamp(fpath.stat().st_mtime).isoformat()
            tmin = tmax = mt + " (mtime)"
        hint_files[str(fpath)] = (tmin, tmax)


def main():
    missing = []
    for agent, root in ROOTS:
        if not root.exists():
            missing.append(str(root))
            continue
        for fpath in sorted(root.rglob("*")):
            if fpath.is_file() and fpath.suffix in (".jsonl", ".json"):
                scan_file(agent, fpath)

    report = {
        "scanned": {a: {"files": per_agent_files[a], "MB": round(per_agent_bytes[a] / 1e6, 1)}
                    for a, _ in ROOTS if per_agent_files[a]},
        "missing_roots": missing,
        "parse_fail_lines": dict(parse_fail_lines),
        "skipped_files": skipped_files,
        "schema_command_key_paths": {f"{a} :: {p}": n for (a, p), n in sorted(key_census.items(), key=lambda x: -x[1])},
        "blocked_result_context_command_keys": {f"{a} :: {p}": n for (a, p), n in sorted(blocked_hits.items(), key=lambda x: -x[1])[:30]},
        "hint_transcripts": {
            "count": len(hint_files),
            "date_min": min((v[0] for v in hint_files.values()), default=None),
            "date_max": max((v[1] for v in hint_files.values()), default=None),
        },
        "config_file_entire_hits_excluded": dict(config_file_hits),
        "deduped_progress_copies": stats["deduped_progress_copies"],
        "entire_verb_census": dict(sorted(entire_census.items(), key=lambda x: -x[1])),
        "census_examples": {k: v for k, v in census_examples.items()},
        "target_matches": target_matches,
    }
    out = Path(sys.argv[1]) if len(sys.argv) > 1 else Path("report.json")
    out.write_text(json.dumps(report, indent=2))
    print(json.dumps({k: report[k] for k in ("scanned", "missing_roots", "hint_transcripts",
                                             "entire_verb_census", "deduped_progress_copies")}, indent=2))
    print(f"\nTARGET MATCHES: {len(target_matches)}")
    for m in target_matches:
        print(f"  [{m['target']}] {m['agent']} {m['ts']} :: {m['cmd']}")
    print(f"\nfull report -> {out}")


main()

