        if not toks:
            continue
        binbase, phrase = entire_verbs(toks)
        if phrase is None:
            continue
        dedup_key = (cmd.strip(), ts if ts else f"{fpath}:{lineno}")
        is_dup = dedup_key in seen_dedup
        seen_dedup.add(dedup_key)
        if fpath.name in CONFIG_BASENAMES:
            config_file_hits[phrase] += 1
            continue
        if is_dup:
            stats["deduped_progress_copies"] += 1
            continue
        entire_census[phrase] += 1
        if len(census_examples[phrase]) < 3:
            census_examples[phrase].append(cmd.strip().replace("\n", " ⏎ ")[:200])
        tgt = classify_target(phrase)
        if tgt:
            target_matches.append({
                "target": tgt, "agent": agent, "file": str(fpath), "ts": ts,
                "json_path": path, "binary": binbase,
                "cmd": cmd.strip().replace("\n", " ⏎ ")[:300],
            })


def scan_line_obj(agent, fpath, obj, raw_ts, lineno):
    hits = []
    ctx = {"agent": agent}
    walk(obj, "", False, hits, ctx)
    for path, cmd in hits:
        process_command(agent, fpath, raw_ts, path, cmd, lineno)


def get_ts(obj):
    if isinstance(obj, dict):
        for k in ("timestamp", "ts", "created_at", "createdAt", "time"):
            v = obj.get(k)
            if isinstance(v, str) and len(v) >= 8:
                return v
    return None


def scan_file(agent, fpath):
    try:
        size = fpath.stat().st_size
    except OSError:
        return
    if size > 500 * 1024 * 1024:
        skipped_files.append((str(fpath), f"{size} bytes > 500MB cap"))
        return
    per_agent_files[agent] += 1
    per_agent_bytes[agent] += size
    has_hint = False
    tmin = tmax = None
    if fpath.suffix == ".jsonl":
        try:
            with open(fpath, "r", errors="replace") as f:
                for lineno, line in enumerate(f):
                    if HINT in line:
                        has_hint = True
                    line = line.strip()
                    if not line:
                        continue
                    try:
                        obj = json.loads(line)
                    except Exception:
                        parse_fail_lines[agent] += 1
                        continue
                    ts = get_ts(obj)
                    if ts:
                        if tmin is None or ts < tmin:
                            tmin = ts
                        if tmax is None or ts > tmax:
                            tmax = ts
                    scan_line_obj(agent, fpath, obj, ts, lineno)
        except OSError as e:
            skipped_files.append((str(fpath), f"read error: {e}"))
            return
    else:  # .json
        try:
            text = fpath.read_text(errors="replace")
        except OSError as e:
            skipped_files.append((str(fpath), f"read error: {e}"))
            return
        if HINT in text:
            has_hint = True
        try:
            obj = json.loads(text)
        except Exception:
            parse_fail_lines[agent] += 1
            obj = None
        if obj is not None:
            scan_line_obj(agent, fpath, obj, get_ts(obj), 0)
    if has_hint:
        if tmin is None:
            import datetime
            mt = datetime.datetime.fromtimestamp(fpath.stat().st_mtime).isoformat()
            tmin = tmax = mt + " (mtime)"
        hint_files[str(fpath)] = (tmin, tmax)


def main():
    missing = []
    for agent, root in ROOTS:
        if not root.exists():
            missing.append(str(root))
            continue
        for fpath in sorted(root.rglob("*")):
            if fpath.is_file() and fpath.suffix in (".jsonl", ".json"):
                scan_file(agent, fpath)

    report = {
        "scanned": {a: {"files": per_agent_files[a], "MB": round(per_agent_bytes[a] / 1e6, 1)}
                    for a, _ in ROOTS if per_agent_files[a]},
        "missing_roots": missing,
        "parse_fail_lines": dict(parse_fail_lines),
        "skipped_files": skipped_files,
        "schema_command_key_paths": {f"{a} :: {p}": n for (a, p), n in sorted(key_census.items(), key=lambda x: -x[1])},
        "blocked_result_context_command_keys": {f"{a} :: {p}": n for (a, p), n in sorted(blocked_hits.items(), key=lambda x: -x[1])[:30]},
        "hint_transcripts": {
            "count": len(hint_files),
            "date_min": min((v[0] for v in hint_files.values()), default=None),
            "date_max": max((v[1] for v in hint_files.values()), default=None),
        },
        "config_file_entire_hits_excluded": dict(config_file_hits),
        "deduped_progress_copies": stats["deduped_progress_copies"],
        "entire_verb_census": dict(sorted(entire_census.items(), key=lambda x: -x[1])),
        "census_examples": {k: v for k, v in census_examples.items()},
        "target_matches": target_matches,
    }
    out = Path(sys.argv[1]) if len(sys.argv) > 1 else Path("report.json")
    out.write_text(json.dumps(report, indent=2))
    print(json.dumps({k: report[k] for k in ("scanned", "missing_roots", "hint_transcripts",
                                             "entire_verb_census", "deduped_progress_copies")}, indent=2))
    print(f"\nTARGET MATCHES: {len(target_matches)}")
    for m in target_matches:
        print(f"  [{m['target']}] {m['agent']} {m['ts']} :: {m['cmd']}")
    print(f"\nfull report -> {out}")


main()

